import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {Ajv} from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('throws Unknown tool: <name> for an unregistered name', async () => {
      const registry = new ToolRegistry();
      await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
    });

    it('unit test rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      const definition: ToolDefinition = {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      };
      registry.register(definition, async () => {
        executorCalls += 1;
        return 'sunny';
      });

      const response = await registry.execute('get_weather', {});

      expect({calls: executorCalls, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringMatching(/required.*location|missingProperty.*location|location.*required/i),
      });
    });

    it('passes valid input with an unlisted extra property to the executor unchanged', async () => {
      const registry = new ToolRegistry();
      let capturedInput: Record<string, unknown> | undefined;
      let calls = 0;
      registry.register(
        {
          name: 'test_extra',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {a: {type: 'string'}},
          },
        },
        async input => {
          calls++;
          capturedInput = input;
          return 'ok';
        }
      );
      const input = {a: 'val', extra: 123};
      await registry.execute('test_extra', input);
      expect({calls, capturedInput}).toEqual({calls: 1, capturedInput: input});
    });

    it('rejects a wrong-typed field with a message naming the field path and the expected type, and that the message does not contain the offending value', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'test_type',
          description: 'test',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
          },
        },
        async () => 'ok'
      );

      const response = await registry.execute('test_type', {location: 123456789});
      expect({
        hasLocation: /location/.test(response.result),
        hasString: /string/.test(response.result),
        lacksValue: !/123456789/.test(response.result),
      }).toEqual({hasLocation: true, hasString: true, lacksValue: true});
    });

    it('throws at registration time for an uncompilable schema naming the tool', () => {
      const registry = new ToolRegistry();
      expect(() => {
        registry.register(
          {
            name: 'broken_tool',
            description: 'test',
            inputSchema: {
              type: 'object',
              properties: {a: {type: 'not-a-type'}},
            },
          },
          async () => 'ok'
        );
      }).toThrow(/broken_tool/);
    });

    it('validates a function-valued tool definition against the schema current at that call, not a stale cached one', async () => {
      const registry = new ToolRegistry();
      let schemaRef: Record<string, unknown> = {type: 'object', properties: {a: {type: 'string'}}, required: ['a']};
      registry.register(
        () => ({
          name: 'dynamic',
          description: 'test',
          inputSchema: schemaRef,
        }),
        async () => 'ok'
      );

      const res1 = await registry.execute('dynamic', {a: 'val'});
      schemaRef = {type: 'object', properties: {b: {type: 'number'}}, required: ['b']};
      const res2 = await registry.execute('dynamic', {a: 'val'});
      expect({
        res1: res1.result,
        res2Matches: /Validation failed.*b/.test(res2.result),
      }).toEqual({res1: 'ok', res2Matches: true});
    });

    it("compiles a static tool's schema once at registration time", () => {
      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'static_tool_reg',
          description: 'test',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      expect(compileSpy).toHaveBeenCalledTimes(1);
      compileSpy.mockRestore();
    });

    it("does not recompile a static tool's schema across ten execute calls", async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'static_tool_exec',
          description: 'test',
          inputSchema: {type: 'object', properties: {a: {type: 'string'}}},
        },
        async () => 'ok'
      );

      const compileSpy = jest.spyOn(Ajv.prototype, 'compile');
      for (let i = 0; i < 10; i++) {
        await registry.execute('static_tool_exec', {a: 'test'});
      }
      expect(compileSpy).not.toHaveBeenCalled();
      compileSpy.mockRestore();
    });
  });
});

import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import {Ajv, type ValidateFunction, type ErrorObject} from 'ajv';

const ajv = new Ajv({
  strict: false,
  validateFormats: false,
});

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

function getValidationErrorProperty(err?: ErrorObject): string {
  if (!err) return 'input';
  if (err.params && 'missingProperty' in err.params) return String(err.params.missingProperty);
  if (err.instancePath) return err.instancePath;
  const errRecord = err as Record<string, unknown>;
  if (errRecord.dataPath) return String(errRecord.dataPath);
  return 'input';
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCache = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private compileSchema(toolName: string, schema: object): ValidateFunction {
    const cached = this.schemaCache.get(schema);
    if (cached) return cached;
    try {
      const validate = ajv.compile(schema);
      this.schemaCache.set(schema, validate);
      return validate;
    } catch (error) {
      throw new Error(
        `Invalid inputSchema for tool ${toolName}: ${error instanceof Error ? error.message : String(error)}`,
        {cause: error}
      );
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    if (typeof definition !== 'function' && definition.inputSchema) {
      this.compileSchema(definition.name, definition.inputSchema);
    }
    const resolved = this.resolveDefinition(definition);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for validation and rejection behavior. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});

    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = definition.inputSchema ? this.compileSchema(definition.name, definition.inputSchema) : undefined;
    if (!validate || validate(input)) {
      const rawResult = await tool.execute(input, context);
      const response = normalizeToolResponse(rawResult);
      log.info('tool', 'execution complete', {
        name,
        rawType: typeof rawResult,
        clientMessageCount: response.clientMessages?.length ?? 0,
        clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
        suppressAssistantResponse: response.suppressAssistantResponse ?? false,
      });
      return response;
    }

    const error = validate.errors?.[0] as ErrorObject | undefined;
    const property = getValidationErrorProperty(error);
    const expectedType = error?.params && 'type' in error.params ? String(error.params.type) : undefined;
    const expected = expectedType ? ` (expected ${expectedType})` : '';
    return {result: `Validation failed for ${property}: ${error?.message}${expected}`};
  }
}

